export const EMOJI_TOTAL = 1906;

const SEARCH_STRIP = /[\uFE00-\uFE0F\u200D]/g;

function normalizeSearch(s: string): string {
  return s.replace(SEARCH_STRIP, '').toLowerCase();
}

const normToReal = new Map<string, string>();
{
  for (const cat of EMOJI_CATEGORIES) {
    for (const e of cat.emojis) {
      const n = normalizeSearch(e);
      if (!normToReal.has(n)) normToReal.set(n, e);
    }
  }
}

const catOrder = new Map<string, number>();
{
  let idx = 0;
  for (const cat of EMOJI_CATEGORIES) {
    for (const e of cat.emojis) {
      if (!catOrder.has(e)) catOrder.set(e, idx++);
    }
  }
}

