export function searchEmojis(query: string, maxResults = 80): string[] {
  const q = query.trim();
  if (!q) return [];
  const normQ = normalizeSearch(q);
  const matched = new Set<string>();
  if (normQ) {
    const exact = normToReal.get(normQ);
    if (exact) matched.add(exact);
  }
  const qKey = q.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (qKey) {
    for (const [kw, glyphs] of Object.entries(EMOJI_SEARCH_KEYWORDS)) {
      if (kw.startsWith(qKey) || qKey.startsWith(kw)) {
        for (const g of glyphs) {
          const real = normToReal.get(g) || g;
          matched.add(real);
        }
      }
    }
  }
  if (normQ.length >= 2) {
    for (const [n, real] of normToReal) {
      if (n !== normQ && n.includes(normQ)) matched.add(real);
    }
  }
  const out = Array.from(matched);
  out.sort((a, b) => (catOrder.get(a) ?? 1e9) - (catOrder.get(b) ?? 1e9));
  return out.slice(0, maxResults);
}
